function model(p) {
  // An illustrative story: one member's address change crossing eight systems. Systems, timings and names are
  // made up for teaching. realMs = milliseconds after Maria taps Save; start/dur = playback seconds.
  const ed = Math.round(p.style) === 1, outage = Math.round(p.outage) === 1, sf = Math.round(p.names) === 1;
  const OLD = '9 Elm Street', NEW = '14 Oak Lane';
  const N = sf
    ? { portal: 'Experience Cloud portal', gateway: 'MuleSoft API', crm: 'Health Cloud', mdm: 'Data Cloud unified profile',
        bus: ed ? 'Platform Events (Pub/Sub API)' : 'Apex callouts (sync)', claims: 'Claims system', billing: 'Billing system',
        analytics: 'CRM Analytics', queue: 'Event replay' }
    : { portal: 'Member portal', gateway: 'API gateway', crm: 'CRM', mdm: 'Master data', bus: ed ? 'Event bus' : 'Integration layer',
        claims: 'Claims system', billing: 'Billing system', analytics: 'Analytics', queue: 'Retry queue' };
  const ROLE = {
    portal: 'Where Maria signs in and edits her profile. It only shows what the back end tells it.',
    gateway: 'The front door for every API call: checks who is calling, applies limits, routes the request.',
    crm: 'System of record for the member. It owns the address and decides when the change is final.',
    mdm: 'Keeps one golden profile per member by matching records from every system.',
    bus: ed ? 'Carries the AddressChanged event to every subscriber. The publisher never waits for them.'
      : 'Makes one synchronous call per downstream system, in a fixed order, and waits for each answer.',
    claims: 'Pays and explains claims; sends letters to the member\'s address.',
    billing: 'Sends premium bills to the member\'s address. In this story it is the system that goes down.',
    analytics: 'Reporting and models, for example care outreach by region. Needs the address for geography.',
    queue: 'Holds events a subscriber has not taken yet and redelivers them when it is back.'
  };
  const ICON = { portal: 'app-window', gateway: 'shield-check', crm: 'contact', mdm: 'database', bus: ed ? 'radio-tower' : 'cable',
    claims: 'file-text', billing: 'receipt', analytics: 'chart-column', queue: 'inbox' };
  const HOLDERS = ['crm', 'mdm', 'claims', 'billing', 'analytics'], DOWNSTREAM = HOLDERS.slice(1);
  const ids = ['portal', 'gateway', 'crm', 'mdm', 'bus', 'claims', 'billing', 'analytics'].concat(ed ? ['queue'] : []);
  const systems = ids.map(id => ({ id, name: N[id], role: ROLE[id], icon: ICON[id], holdsAddress: HOLDERS.includes(id) }));
  const st = Object.fromEntries(ids.map(id => [id, 'idle']));
  let member = 'idle', queue = 0, t = 0;
  const scenes = [], events = [];
  const scene = (title, caption) => scenes.push({ i: scenes.length, title, caption, start: +t.toFixed(2) });
  const add = (station, kind, realMs, dur, note, path, set, extra) => {
    extra = extra || {};
    Object.assign(st, set || {});
    if (extra.member) member = extra.member;
    if (extra.queue != null) queue = extra.queue;
    events.push({ i: events.length, scene: scenes.length - 1, station, kind, realMs, start: +t.toFixed(2), dur, note,
      path: path && path.length ? path : [station], fail: !!extra.fail,
      snap: { status: Object.assign({}, st), member, queue, addr: Object.fromEntries(HOLDERS.map(h => [h, st[h] === 'new' ? 'new' : 'old'])) } });
    t += dur;
  };
  const back = ['crm', 'gateway', 'portal', 'maria'];

  scene('Maria moves house', 'Maria, a member of the health plan, has just moved. She opens the member portal on her phone to update her address.');
  add('maria', 'type', -20000, 1.8, 'Maria types her new address, ' + NEW + ', into the portal on her phone.', [], {}, { member: 'typing' });
  add('portal', 'submit', 0, 1.8, 'She taps Save. The portal sends the change on its way.', ['maria', 'portal'], { portal: 'pass' }, { member: 'saving' });
  scene('Through the front door', 'The API gateway checks the request really comes from Maria. Then the CRM, the system of record, saves it.');
  add('gateway', 'auth', 40, 1.6, 'The API gateway checks that Maria is signed in and passes the request on.', ['portal', 'gateway'], { gateway: 'pass' });
  add('crm', 'save', 250, 1.8, 'The CRM, the system of record, saves the new address on Maria\'s member record.', ['gateway', 'crm'], { crm: 'new' });
  if (outage) {
    scene('Trouble downstream', 'At that very moment, the billing system goes down for maintenance. Nobody upstream knows yet.');
    add('billing', 'outage', 280, 2.6, 'Billing goes down for maintenance. Nobody upstream knows yet.', [], { billing: 'down' });
  }
  let failAt = -1;
  if (ed) {
    scene('One announcement', 'The CRM does not call anyone. It publishes one AddressChanged event and tells Maria her change is saved.');
    add('bus', 'publish', 300, 1.8, 'The CRM publishes one AddressChanged event to the event bus. It waits for nobody.', ['crm', 'bus'], { bus: 'pass' });
    add('portal', 'saved', 350, 1.8, 'Maria sees "Saved" after 0.35 seconds and gets on with her day.', back, {}, { member: 'saved' });
    scene('Everyone who cares, listens', 'Each system that needs the address picks up the event on its own, at its own pace.');
    add('mdm', 'deliver', 450, 1.5, 'Master data picks up the event and updates the golden profile.', ['bus', 'mdm'], { mdm: 'new' });
    if (outage) add('billing', 'queued', 480, 1.6, 'Billing is down, so its copy waits in the queue. Nothing fails.', ['bus', 'queue'], { queue: 'queued' }, { queue: 1 });
    add('claims', 'deliver', 520, 1.5, 'Claims picks up the event. Claim letters will go to the new address.', ['bus', 'claims'], { claims: 'new' });
    if (!outage) add('billing', 'deliver', 560, 1.5, 'Billing picks up the event. The next bill goes to the new address.', ['bus', 'billing'], { billing: 'new' });
    add('analytics', 'deliver', 600, 1.5, 'Analytics picks up the event and moves Maria to her new region.', ['bus', 'analytics'], { analytics: 'new' });
    if (outage) {
      scene('Billing comes back', 'Twenty minutes later billing is back. The waiting event is delivered and billing catches up by itself.');
      add('billing', 'recover', 1200000, 1.6, 'Twenty minutes later, billing is back up.', [], { billing: 'old' });
      add('billing', 'catchup', 1200400, 1.8, 'The waiting event is delivered. Billing updates the address with nobody stepping in.', ['queue', 'billing'], { billing: 'new', queue: 'idle' }, { queue: 0 });
    }
  } else {
    scene('One call at a time', 'The CRM calls each system that needs the address, one after another, and waits for every answer before it can reply.');
    add('bus', 'call', 300, 1.4, 'The CRM starts its calls through the integration layer and waits. So does Maria.', ['crm', 'bus'], { bus: 'busy' });
    add('mdm', 'sync', 550, 1.4, 'Call 1: master data updates and answers. 0.55 seconds so far.', ['bus', 'mdm'], { mdm: 'new' });
    add('claims', 'sync', 900, 1.4, 'Call 2: claims updates and answers. 0.9 seconds so far.', ['bus', 'claims'], { claims: 'new' });
    if (outage) {
      scene('Waiting on billing', 'Call 3 goes to billing, which is down. The CRM keeps waiting, and so does Maria.');
      add('billing', 'call', 900, 2.4, 'Call 3 goes to billing. No answer. The CRM waits, and so does Maria.', ['bus', 'billing'], {});
      failAt = events.length;
      add('billing', 'timeout', 10900, 1.6, 'After 10 seconds the call times out.', [], { bus: 'failed' }, { fail: true });
      scene('Something went wrong', 'The CRM gives up and undoes its own save. Analytics is never called. Maria sees an error.');
      add('crm', 'rollback', 10950, 1.6, 'The CRM rolls back its own save. Analytics is never called.', [], { crm: 'rolledback', analytics: 'skipped' });
      add('portal', 'error', 11000, 1.8, 'Maria sees "Something went wrong" after 11 seconds. Did it save? She cannot tell.', back, {}, { member: 'error', fail: true });
      scene('Out of step', 'Billing comes back twenty minutes later, but nobody resends the change.');
      add('billing', 'recover', 1200000, 1.8, 'Billing is back up, but nobody resends the change. It still has the old address.', [], { billing: 'old' });
    } else {
      scene('And the next, and the next', 'Billing and analytics are called in turn. Every answer adds to Maria\'s wait.');
      add('billing', 'sync', 1250, 1.4, 'Call 3: billing updates and answers. 1.25 seconds so far.', ['bus', 'billing'], { billing: 'new' });
      add('analytics', 'sync', 1500, 1.4, 'Call 4: analytics updates and answers. 1.5 seconds so far.', ['bus', 'analytics'], { analytics: 'new' });
      add('portal', 'saved', 1550, 1.8, 'Only now can the CRM reply. Maria sees "Saved" after 1.55 seconds.', back, { bus: 'pass' }, { member: 'saved' });
    }
  }
  const pre = events[events.length - 1].snap;
  const fin = pre.addr;
  const inconsistent = HOLDERS.filter(h => fin[h] !== fin.crm);
  const updatedBeforeFailure = failAt < 0 ? [] : DOWNSTREAM.filter(h => events[failAt - 1].snap.addr[h] === 'new');
  const saveOk = member === 'saved', consistent = inconsistent.length === 0;
  const responseMs = events.find(e => e.kind === 'saved' || e.kind === 'error').realMs;
  const sec = (responseMs / 1000).toFixed(responseMs < 10000 ? 2 : 0).replace(/0$/, '').replace(/\.$/, '');
  const list = a => a.map(h => N[h]).join(', ').replace(/, ([^,]*)$/, ' and $1');
  const outcome = consistent
    ? 'Every system now has ' + NEW + '. Maria saw "Saved" in ' + sec + ' s' + (outage ? '; billing caught up 20 minutes later.' : '.')
    : list(inconsistent) + ' have ' + NEW + '; ' + list(HOLDERS.filter(h => !inconsistent.includes(h))) + ' still have ' + OLD + '. Her next bill goes to the old house.';
  const soWhat = ed
    ? (outage ? 'So what: with events, an outage in one system becomes a delay for that system, not a failure for the member.'
      : 'So what: Maria gets an instant answer, and each new consumer is one more subscription, not one more call.')
    : (outage ? 'So what: a synchronous chain is as reliable as its weakest link, and failing halfway leaves data out of step.'
      : 'So what: point-to-point works on a good day, but Maria waits for every system and each new one adds a call.');
  scene('So what', soWhat);
  add('maria', 'outcome', events[events.length - 1].realMs, 4.0, outcome, [], {});
  scenes.forEach((s, k) => { s.end = k < scenes.length - 1 ? scenes[k + 1].start : +t.toFixed(2); s.dur = +(s.end - s.start).toFixed(2); });
  const n = HOLDERS.length;
  const integrations = { holders: n, consumers: n - 1, p2pMesh: n * (n - 1) / 2, p2pFromCrm: n - 1, eventPublish: 1, eventSubscriptions: n - 1, eventTotal: n };
  const memberMessage = saveOk ? 'Saved' : 'Something went wrong';
  return {
    style: ed ? 'event' : 'p2p', outage, names: sf ? 'salesforce' : 'generic', oldAddress: OLD, newAddress: NEW,
    systems, holders: HOLDERS, scenes, events, duration: +t.toFixed(2), markers: scenes.map(s => s.start),
    final: { addr: fin, status: pre.status }, memberMessage, saveOk, consistent,
    outOfStep: Object.fromEntries(HOLDERS.map(h => [h, inconsistent.includes(h)])),
    updatedBeforeFailure: Object.fromEntries(DOWNSTREAM.map(h => [h, updatedBeforeFailure.includes(h)])),
    responseMs, responseText: sec + ' s', integrations, outcome, soWhat,
    summary: (ed ? 'Event-driven: ' : 'Point-to-point: ') + 'Maria saw "' + memberMessage + '" after ' + sec + ' s; ' +
      (consistent ? 'all ' + n + ' systems that hold her address agree' + (outage ? ' once billing catches up.' : '.') : inconsistent.length + ' systems are out of step with the CRM.')
  };
}

checkCode:
function check(p) {
  const m = model(p), ed = Math.round(p.style) === 1, out = Math.round(p.outage) === 1, fin = m.final.addr;
  const ordered = m.events.every((e, k) => !k || (e.realMs >= m.events[k - 1].realMs && e.start >= m.events[k - 1].start));
  const flip = model(Object.assign({}, p, { names: 1 - Math.round(p.names) }));
  const namesOnly = flip.memberMessage === m.memberMessage && JSON.stringify(flip.final) === JSON.stringify(m.final);
  const failCase = !ed && out;
  const msgOk = m.memberMessage === (failCase ? 'Something went wrong' : 'Saved') && m.saveOk === !failCase;
  const updated = m.holders.filter(h => fin[h] === 'new');
  let stateOk, what;
  if (failCase) {
    const off = m.holders.filter(h => m.outOfStep[h]), early = m.holders.filter(h => m.updatedBeforeFailure[h]);
    stateOk = fin.crm === 'old' && off.length > 0 && off.join() === early.join();
    what = 'the save failed after ' + m.responseText + ' and the ' + off.length + ' out-of-step systems (' + off.map(h => m.systems.find(x => x.id === h).name).join(', ') +
      ') are exactly those updated before the billing timeout';
  } else {
    stateOk = updated.length === m.holders.length && m.consistent;
    what = 'Maria saw "Saved" after ' + m.responseText + ' and all ' + updated.length + ' of ' + m.holders.length + ' address holders end on the new address';
  }
  return {
    pass: ordered && namesOnly && msgOk && stateOk,
    detail: (ed ? 'Event-driven' : 'Point-to-point') + (out ? ' with billing down: ' : ' with billing up: ') + what + '; ' +
      m.events.length + ' events are in time order' + (ordered ? '' : ' (NOT)') + ' and switching names ' + (namesOnly ? 'changes nothing else.' : 'CHANGES the outcome.')
  };
}
